cat > memo.js << 'EOF'
#!/usr/bin/env node
import readline from 'node:readline';
import Database from 'better-sqlite3';

const db = new Database('memos.db');
db.exec(`CREATE TABLE IF NOT EXISTS memos (id INTEGER PRIMARY KEY, text TEXT)`);

const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

console.log('메모를 입력하세요. "목록" 은 전체 보기, "끝" 은 종료.');
rl.on('line', (line) => {
  const text = line.trim();
  if (text === '끝') {
    db.close();
    return rl.close();
  }
  if (text === '목록') {
    const memos = db.prepare('SELECT id, text FROM memos ORDER BY id').all();
    memos.forEach(memo => console.log(`${memo.id}. ${memo.text}`));
    return;
  }
  if (text !== '') {
    db.prepare('INSERT INTO memos (text) VALUES (?)').run(text);
    console.log('✓ 저장됨');
  }
});
EOF

cat > organize_downloads.py << 'EOF'
#!/usr/bin/env python3
import os
import shutil
from pathlib import Path
from collections import defaultdict

def organize_downloads_by_extension(downloads_path):
    downloads_dir = Path(downloads_path)

    if not downloads_dir.exists():
        print(f"❌ 오류: {downloads_path} 폴더를 찾을 수 없습니다.")
        return

    files_by_ext = defaultdict(list)

    for file in downloads_dir.iterdir():
        if file.is_file():
            if file.suffix:
                ext = file.suffix.lstrip('.')
            else:
                ext = "기타"
            files_by_ext[ext].append(file)

    if not files_by_ext:
        print("📁 정렬할 파일이 없습니다.")
        return

    print("📂 Downloads 폴더 파일 정렬 시작...\n")

    for ext, files in sorted(files_by_ext.items()):
        folder_name = f"[{ext.upper()}]"
        folder_path = downloads_dir / folder_name

        folder_path.mkdir(exist_ok=True)

        for file in files:
            dest = folder_path / file.name

            if dest.exists():
                stem = file.stem
                dest = folder_path / f"{stem}_1{file.suffix}"

            shutil.move(str(file), str(dest))
            print(f"✓ {file.name} → {folder_name}/")

        print(f"  ({len(files)}개 파일)\n")

    print("✅ 정렬 완료!")

    print("\n📊 정렬 결과:")
    for folder in sorted(downloads_dir.iterdir()):
        if folder.is_dir() and folder.name.startswith('['):
            file_count = len(list(folder.iterdir()))
            print(f"  {folder.name}: {file_count}개 파일")

if __name__ == "__main__":
    organize_downloads_by_extension("./downloads")
EOF
